import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"CDS Jewel -- RADOS Tail Latency Improvements","description":"","frontmatter":{"title":"CDS Jewel -- RADOS Tail Latency Improvements","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-03T00:00:00.000Z","tags":["Ceph","分布式存储","低延迟","性能优化","RADOS"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.md","filePath":"posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.md"};function n(r,l,p,a,_,D){return t(),o("div",null,[...l[0]||(l[0]=[i("<p>会议纪要</p><p>会议主题：Ceph 分布式存储性能优化讨论</p><p>会议时间：2023年11月（具体日期未提及）</p><p>参会人员：Sam、Mark、Guang、Anakin、Castle 等</p><p>会议内容：</p><p><strong>一、低延迟改进</strong></p><ol><li><strong>心跳优化</strong>：Sam 提出通过发送消息给监控器来主动声明自身死亡，从而提高失败检测的效率，减少延迟。</li><li><strong>慢 OSD 自动检测</strong>：讨论了自动检测慢速 OSD 并将其标记为不可用，以避免整个集群速度下降。</li><li><strong>读取优化</strong>：讨论了通过并行读取多个副本来提高读取速度，并考虑使用新的存储引擎来优化性能。</li></ol><p><strong>二、存储引擎优化</strong></p><ol><li><strong>文件存储优化</strong>：讨论了文件存储的复杂性，并考虑使用新的存储引擎来优化性能。</li><li><strong>LevelDB 和 RocksDB</strong>：讨论了 LevelDB 和 RocksDB 在压缩过程中的性能问题，并考虑使用 RocksDB 来替代 LevelDB。</li></ol><p><strong>三、其他讨论</strong></p><ol><li><strong>OSD 性能统计</strong>：讨论了收集 OSD 性能统计数据，以便更好地了解性能瓶颈。</li><li><strong>优先级处理</strong>：讨论了请求优先级处理，确保来自主节点的请求优先处理。</li><li><strong>数据分区</strong>：讨论了确保数据在 OSD 之间均匀分布，以避免性能瓶颈。</li></ol><p><strong>四、行动计划</strong></p><ol><li>Sam 将继续优化心跳机制和慢 OSD 检测。</li><li>Guang 将研究并行读取多个副本来提高读取速度。</li><li>Castle 将研究新的存储引擎，并考虑使用 RocksDB 替代 LevelDB。</li><li>Sam 和 Guang 将收集 OSD 性能统计数据。</li></ol><p><strong>五、关键术语</strong></p><ul><li>Ceph</li><li>分布式存储</li><li>低延迟</li><li>慢 OSD</li><li>文件存储</li><li>LevelDB</li><li>RocksDB</li><li>数据分区</li></ul><p><strong>总结</strong>：</p><p>本次会议主要讨论了 Ceph 分布式存储中 RADOS 的低延迟优化方案，包括心跳优化、慢 OSD 自动检测、读取优化、存储引擎优化等方面。会议确定了后续行动计划，并明确了关键术语。</p><p>改进点：</p><ol><li>保留了所有会议讨论的关键议题。</li><li>确保了行动计划和关键术语的准确性。</li><li>优化了总结的流畅性和结构性。</li></ol>",19)])])}const c=e(s,[["render",n]]);export{S as __pageData,c as default};
